// Disposable fixture generated by Node libsignal 0.107.0; never production keys.
import XCTest
import SignalBridge
@testable import ENCPTD

final class PCChatInteropTests: XCTestCase {
    private struct Fixture: Decodable {
        let bobID: String; let pcID: String; let registrationID: UInt32
        let bobIdentity: Data; let pcIdentity: Data; let ciphertext: Data; let number: String
        let preKeys: [String: Data]; let signed: [String: Data]; let kyber: [String: Data]
    }
    func testWindowsSignalMessageDecryptsOnIPhoneWithSameSafetyNumberAndDates() throws {
        let fixture = try JSONDecoder().decode(Fixture.self, from: Data(base64Encoded: "")!)
        var state = VaultState()
        state.ownerID = fixture.bobID; state.identity = fixture.bobIdentity; state.registrationID = fixture.registrationID
        state.preKeys = fixture.preKeys; state.signedKeys = fixture.signed; state.kyberKeys = fixture.kyber
        state.trusted[fixture.pcID] = fixture.pcIdentity
        let store = SignalStore(state: state)
        let pc = try ProtocolAddress(name: fixture.pcID, deviceId: 1), local = try ProtocolAddress(name: fixture.bobID, deviceId: 1)
        let clear = try signalDecryptPreKey(message: PreKeySignalMessage(bytes: fixture.ciphertext), from: pc, localAddress: local,
            sessionStore: store, identityStore: store, preKeyStore: store, signedPreKeyStore: store, kyberPreKeyStore: store, context: NullContext())
        let message = try JSONDecoder().decode(MessageContent.self, from: clear)
        XCTAssertEqual(message.text, "PC-to-iPhone interop fixture")
        XCTAssertEqual(message.created.timeIntervalSince1970, 1900000000, accuracy: 0.001)
        XCTAssertEqual(try XCTUnwrap(message.expiresAt).timeIntervalSince1970, 1900086400, accuracy: 0.001)
        let contact = Contact(id: fixture.pcID, username: "pc_fixture", identityKey: fixture.pcIdentity)
        let number = try ConversationSafetyNumber.make(ownerID: fixture.bobID, identity: store.identityKeyPair(context: NullContext()), contact: contact)
        XCTAssertEqual(number.filter(\.isNumber), fixture.number)
    }
}
